import os
import json

import coverage

test_to_line_coverage = {}  # map from test to filenames and lines of production code
line_to_test_coverage = {}  # map from line of production code to tests


def build_test_to_code_traceability(report, omit):
    """
    Creates traceability in both directions:
    from test to production code line
    from production code line to tests running this line
    :param report: pytest report information
    :param omit: lists of file name patterns. Files that match `omit` will not be measured.
    :return: None, just modify global data structures
    """
    test_name = report.nodeid[0:report.nodeid.index('[')] if '[' in report.nodeid else report.nodeid   # it looks like:    test_prod_code.py::test_one
    if report.when == "setup":  # means: we are after test setup section
        cov = _start_processing_coverage(omit)
        _push_coverage_object(cov, test_name)

    elif report.when == "call":  # means: we are after test execution section
        cov = _pop_coverage_object(test_name)
        _stop_processing_coverage(cov)
        data = cov.get_data()
        production_files = [fname for fname in data.measured_files() if ("test_" not in fname) and ("conftest" not in fname)]
        for filename in production_files:
            covered_lines = data.lines(filename)
            _collect_codelines_touched_by_given_test(covered_lines, filename, test_name)
            _collect_tests_touching_given_codeline(covered_lines, filename, test_name)

    elif report.when == "teardown":
        cov = _pop_coverage_object(test_name)
        _stop_processing_coverage(cov)


def _start_processing_coverage(omit):
    omit.extend(['*/mock/mock.py', '*/pluggy/callers.py', '*/pluggy/hooks.py',
                 '*/pluggy/manager.py', '*/pluggy/_tracing.py', '*/more_itertools/more.py'])
    cov = coverage.Coverage(branch=True,
                            omit=omit)  # may it run in parallel with normal coverage check or pytest cov plugin?
    cov.start()
    return cov


def _stop_processing_coverage(cov):
    if cov:
        cov.stop()


def _push_coverage_object(cov, test_name):
    if test_name in test_to_line_coverage:
        test_to_line_coverage[test_name]['coverage_object'] = cov
    else:
        test_to_line_coverage[test_name] = {'coverage_object': cov}


def _pop_coverage_object(test_name):
    cov = None
    if 'coverage_object' in test_to_line_coverage[test_name]:
        cov = test_to_line_coverage[test_name].pop('coverage_object')
    return cov


def _collect_codelines_touched_by_given_test(covered_lines, filename, test_name):
    test_to_line_coverage[test_name][filename] = covered_lines


def _collect_tests_touching_given_codeline(covered_lines, filename, test_name):
    for line_number in covered_lines:
        line_number_in_file = f'{filename}:{line_number}'
        if line_number_in_file in line_to_test_coverage:
            if test_name not in line_to_test_coverage[line_number_in_file]:  # next round of parametric tests
                line_to_test_coverage[line_number_in_file].append(test_name)
        else:
            line_to_test_coverage[line_number_in_file] = [test_name]


def serialize_test_to_code_traceability(by_folders=()):
    """
    Storing data from test to code traceability dictionaries into json files
    :return:
    """
    sorted_line_to_test_coverage = sort_by_number_of_tests_running_given_code_line(traceability_dict=line_to_test_coverage)
    final_line_to_test_coverage = extend_key_with_number_of_tests_touching_code_line(sorted_line_to_test_coverage)

    serialize_to_json(test_to_line_coverage, 'logs', 'test_to_line_coverage')
    serialize_to_json(final_line_to_test_coverage, 'logs', 'line_to_test_coverage')

    for folder in by_folders:
        module_pattern = f'/{folder}/'
        module_traceability = extract_traceability_for_path_pattern(final_line_to_test_coverage, module_pattern)
        serialize_to_json(module_traceability, 'logs', f'line_to_test_coverage_{folder}')


def sort_by_number_of_tests_running_given_code_line(traceability_dict):
    """
    :param traceability_dict:
    :return:
    """
    def by_number_of_tests(elem1):
        _, tests1 = elem1
        return len(tests1)

    traceability_list = traceability_dict.items()  # list of pairs (code_line, tests_running_that_code_line)
    return sorted(traceability_list, key=by_number_of_tests, reverse=True)


def extend_key_with_number_of_tests_touching_code_line(traceability):
    """
    Extend from:                  /home/ute/ta_repositories/ute_ue/ute_ue/ue_characteristics.py:33
    to:             Touched_line: /home/ute/ta_repositories/ute_ue/ute_ue/ue_characteristics.py:33; touched by 42 tests:
    """
    def build_touched_line_info(elem):
        code_line, tests_running_code_line = elem
        touched_line_info = f'Touched_line: {code_line}; touched by {len(tests_running_code_line)} tests:'
        return touched_line_info, tests_running_code_line

    return list(map(build_touched_line_info, traceability))


def extract_traceability_for_path_pattern(traceability, path_pattern):
    """
    Extract that part of traceability that is related to files selected  by path_pattern
    :param path_pattern: regexp used to select files
    :return: narrowed traceability data structure
    """
    return [elem for elem in traceability if path_pattern in elem[0]]


def serialize_to_json(traceability, directory, file_name):
    """
    :param traceability:
    :param directory:
    :param file_name:
    :return:
    """
    if not os.path.exists(directory):
        os.mkdir(directory)
    full_path = os.path.join(directory, f'{file_name}.json')
    with open(full_path, 'w') as file:
        json.dump(traceability, file, indent=2)
